// The heavy kernel's body (SPEC §7.5): trigger e on one warp, this thread being lane `lane`.
// The lanes' emits together equal fan_total_trigger's.
template <class Sink>
__device__ inline void fan_total_trigger_warp(const GraphView& g, const Params& p, std::uint32_t e, std::uint32_t lane, Sink& out) {
  const std::uint32_t v_U = g.src[e];
  const std::uint32_t v_V = g.dst[e];
  const std::int64_t t = g.ts[e];
  const std::int64_t p_delta_fan = p.span;
  // visibility (SPEC v2 §6.1), once per trigger: stream sees eid <= e, timestamp sees ts <= t
  const std::uint32_t vis_e = p.ts_visibility ? kAnyEid : e;
  const std::int64_t vis_t = p.ts_visibility ? t : kNoUpper;
  if (v_U == v_V) return;
  if (lane == 0) {  // heavy kernel: nothing else reads this root check, so lane 0 runs it alone
    // stage counterparties (union, check)
    // union V.in ∪ V.out over distinct nodes, as |V.in| + |V.out \ V.in|: count V.in (T-CSR, distinct-first), then scan V.out (T-CSR, distinct-first) and keep the elements whose probe of V.in (P-CSR) finds no edge
    // no materialization: C is used only through len(), so the elements that pass the filters are counted
    // e1 in V.in: ts >= t - delta_fan + 1, visible: eid <= eid(e0) (stream) or ts <= t (timestamp), set once per trigger
    // e2 in V.out: ts >= t - delta_fan + 1, visible: eid <= eid(e0) (stream) or ts <= t (timestamp), set once per trigger
    std::int64_t len_C = 0;
    const std::int64_t lo_e1 = t - p_delta_fan + 1, hi_e1 = vis_t;
    const std::int64_t lo_e2 = t - p_delta_fan + 1, hi_e2 = vis_t;
    const Range r_e1 = g.in.range(v_V, lo_e1, hi_e1, vis_e);
    for (std::uint32_t j_e1 = r_e1.lo; j_e1 < r_e1.hi; ++j_e1) {
      if (!g.in.distinct_first(j_e1, r_e1.lo)) continue;
      const std::uint32_t v_Y = g.in.nbr[j_e1];
      if (v_Y == v_V) continue;
      ++len_C;
    }
    const Range r_e2 = g.out.range(v_V, lo_e2, hi_e2, vis_e);
    for (std::uint32_t j_e2 = r_e2.lo; j_e2 < r_e2.hi; ++j_e2) {
      if (!g.out.distinct_first(j_e2, r_e2.lo)) continue;
      const std::uint32_t v_Y = g.out.nbr[j_e2];
      if (v_Y == v_V) continue;
      if (g.pin.pair_exists(v_V, v_Y, lo_e1, hi_e1, vis_e) != kNoTs) continue;  // in V.in
      ++len_C;
    }
    const bool ok_counterparties = len_C != 0;
    if (ok_counterparties) out.emit(len_C, 2);
  }
}

